async function run(){try{console.log("Initializing DB...");await db.initialize();console.log("Initializing Roles...");await rolesManager.initialize();console.log("\n--- Roles Cache ---");for(const[e,o]of rolesManager.roles.entries()){console.log(`Role ID: ${e}`);console.log(`Name: ${o.name}`);console.log(`Permissions count: ${o.permissions.length}`);console.log("Permissions:",o.permissions);console.log("-------------------")}process.exit(0)}catch(e){console.error("Error inspecting roles:",e);process.exit(1)}}require("dotenv").config({path:"../.env"});require("./module-alias-setup.js");const{db:db}=require("@b/db"),{rolesManager:rolesManager}=require("@b/utils/roles");run();